import{_ as n,c as a,aU as t,a as l}from"./chunks/framework.DIXiA2XH.js";const e="/assets/c02.CeNwRYi6.png",i="/assets/c03.BqFuo7EG.png",p="/assets/c04.BNhn65Pu.png",r="/assets/c05.yj9JiO1G.png",d="/assets/c06.dXmNP2EA.png",f=JSON.parse('{"title":"进制","description":"","frontmatter":{},"headers":[],"relativePath":"note/back-end/c/进制.md","filePath":"note/back-end/c/进制.md","lastUpdated":1784375236000}'),c={name:"note/back-end/c/进制.md"};function b(u,s,o,g,m,h){return l(),a("div",null,[...s[0]||(s[0]=[t('<h1 id="进制" tabindex="-1">进制 <a class="header-anchor" href="#进制" aria-label="Permalink to &quot;进制&quot;">​</a></h1><p>感觉还是挺重要的 还是决定单开一个着重讲解下</p><ul><li>进制也就是进位制，是人们规定的一种进位方法</li><li>对于任何一种进制—X进制，就表示某一位置上的数运算时是逢X进一位 <ul><li>十进制是逢十进一，十六进制是逢十六进一，二进制就是逢二进一，以此类推，x进制就是逢x进位</li></ul></li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">十进制</th><th style="text-align:left;">二进制</th><th style="text-align:left;">八进制</th><th style="text-align:left;">十六进制</th></tr></thead><tbody><tr><td style="text-align:left;">0</td><td style="text-align:left;">0</td><td style="text-align:left;">0</td><td style="text-align:left;">0</td></tr><tr><td style="text-align:left;">1</td><td style="text-align:left;">1</td><td style="text-align:left;">1</td><td style="text-align:left;">1</td></tr><tr><td style="text-align:left;">2</td><td style="text-align:left;">10</td><td style="text-align:left;">2</td><td style="text-align:left;">2</td></tr><tr><td style="text-align:left;">3</td><td style="text-align:left;">11</td><td style="text-align:left;">3</td><td style="text-align:left;">3</td></tr><tr><td style="text-align:left;">4</td><td style="text-align:left;">100</td><td style="text-align:left;">4</td><td style="text-align:left;">4</td></tr><tr><td style="text-align:left;">5</td><td style="text-align:left;">101</td><td style="text-align:left;">5</td><td style="text-align:left;">5</td></tr><tr><td style="text-align:left;">6</td><td style="text-align:left;">110</td><td style="text-align:left;">6</td><td style="text-align:left;">6</td></tr><tr><td style="text-align:left;">7</td><td style="text-align:left;">111</td><td style="text-align:left;">7</td><td style="text-align:left;">7</td></tr><tr><td style="text-align:left;">8</td><td style="text-align:left;">1000</td><td style="text-align:left;">10</td><td style="text-align:left;">8</td></tr><tr><td style="text-align:left;">9</td><td style="text-align:left;">1001</td><td style="text-align:left;">11</td><td style="text-align:left;">9</td></tr><tr><td style="text-align:left;">10</td><td style="text-align:left;">1010</td><td style="text-align:left;">12</td><td style="text-align:left;">A</td></tr><tr><td style="text-align:left;">11</td><td style="text-align:left;">1011</td><td style="text-align:left;">13</td><td style="text-align:left;">B</td></tr><tr><td style="text-align:left;">12</td><td style="text-align:left;">1100</td><td style="text-align:left;">14</td><td style="text-align:left;">C</td></tr><tr><td style="text-align:left;">13</td><td style="text-align:left;">1101</td><td style="text-align:left;">15</td><td style="text-align:left;">D</td></tr><tr><td style="text-align:left;">14</td><td style="text-align:left;">1110</td><td style="text-align:left;">16</td><td style="text-align:left;">E</td></tr><tr><td style="text-align:left;">15</td><td style="text-align:left;">1111</td><td style="text-align:left;">17</td><td style="text-align:left;">F</td></tr><tr><td style="text-align:left;">16</td><td style="text-align:left;">10000</td><td style="text-align:left;">20</td><td style="text-align:left;">10</td></tr></tbody></table><h2 id="二进制" tabindex="-1">二进制 <a class="header-anchor" href="#二进制" aria-label="Permalink to &quot;二进制&quot;">​</a></h2><ul><li>二进制是计算技术中广泛采用的一种数制。二进制数据是用0和1两个数码来表示的数 <ul><li>它的基数为2，进位规则是“逢二进一”，借位规则是“借一当二”</li></ul></li><li>当前的计算机系统使用的基本上是二进制系统，<strong>数据在计算机中主要是以补码的形式存储的</strong></li><li>十进制转化二进制的方法： <ul><li>用十进制数除以2，分别取余数和商数，商数为0的时候，将余数倒着数就是转化后的结果</li></ul></li></ul><p><img src="'+e+'" alt=""></p><p>口诀：除二取余，倒序排列法</p><h2 id="八进制" tabindex="-1">八进制 <a class="header-anchor" href="#八进制" aria-label="Permalink to &quot;八进制&quot;">​</a></h2><ul><li>八进制，Octal，缩写OCT或O，一种以8为基数的计数法，采用0，1，2，3，4，5，6，7八个数字，逢八进1 <ul><li>一些编程语言中常常以数字0开始表明该数字是八进制</li></ul></li><li>八进制的数和二进制数可以按位对应（八进制一位对应二进制三位），因此常应用在计算机语言中</li><li>八进制和二进制互转：</li></ul><p><img src="'+i+'" alt=""></p><ul><li>十进制转化八进制的方法： <ul><li>用十进制数除以8，分别取余数和商数，商数为0的时候，将余数倒着数就是转化后的结果 <img src="'+p+'" alt=""></li></ul></li></ul><h2 id="十六进制" tabindex="-1">十六进制 <a class="header-anchor" href="#十六进制" aria-label="Permalink to &quot;十六进制&quot;">​</a></h2><ul><li>十六进制（英文名称：Hexadecimal），同我们日常生活中的表示法不一样，它由0-9，A-F组成，字母不区分大小写 <ul><li>与10进制的对应关系是：0-9对应0-9，A-F(或a-f)对应10-15</li></ul></li><li>十六进制的数和二进制数可以按位对应（<strong>十六进制一位对应二进制四位</strong>），因此常应用在计算机语言中</li><li>十六进制和二进制互转： <img src="'+r+'" alt=""></li><li>十进制转化十六进制的方法： <ul><li>用十进制数除以16，分别取余数和商数，商数为0的时候，将余数倒着数就是转化后的结果 <img src="'+d+`" alt=""></li></ul></li></ul><h2 id="c语言如何表示相应进制数" tabindex="-1">C语言如何表示相应进制数 <a class="header-anchor" href="#c语言如何表示相应进制数" aria-label="Permalink to &quot;C语言如何表示相应进制数&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">十进制</th><th style="text-align:left;">以正常数字1-9开头，如15</th></tr></thead><tbody><tr><td style="text-align:left;">八进制</td><td style="text-align:left;">以数字0开头，如017</td></tr><tr><td style="text-align:left;">十六进制</td><td style="text-align:left;">以0x或0X开头，如0xf</td></tr><tr><td style="text-align:left;">二进制</td><td style="text-align:left;">以0b或0B开头，如0b1111</td></tr><tr><td style="text-align:left;">示例代码：</td><td style="text-align:left;"></td></tr></tbody></table><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>int main() {</span></span>
<span class="line"><span>    // 十进制方式赋值</span></span>
<span class="line"><span>    int a = 15;</span></span>
<span class="line"><span>    // 八进制方式赋值</span></span>
<span class="line"><span>    int b = 017;</span></span>
<span class="line"><span>    // 十六进制方式赋值</span></span>
<span class="line"><span>    int c = 0xf;</span></span>
<span class="line"><span>    // 二进制方式赋值</span></span>
<span class="line"><span>    int d = 0b1111;</span></span>
<span class="line"><span>    printf(&quot;%d, %d, %d, %d\\n&quot;, a, b, c, d);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><h2 id="数值存储方式" tabindex="-1">数值存储方式 <a class="header-anchor" href="#数值存储方式" aria-label="Permalink to &quot;数值存储方式&quot;">​</a></h2><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>计算机底层都是存储数据都是采用二进制，但二进制也有几种，比如：原码、反码、补码。接下来我们来看看他们之间的关系的意义作用。<br> ● 计算机底层存储的二进制都是：补码！<br> ● 正数的原、反、补码都一样<br> ● 负数的原、反、补码不同<br></p></div><h3 id="原码" tabindex="-1">原码 <a class="header-anchor" href="#原码" aria-label="Permalink to &quot;原码&quot;">​</a></h3><blockquote><p>十进制数按照：除二取余、倒序排列，得到的就是原码。</p></blockquote><ul><li>10 -&gt; 0000 1010</li><li>-10 -&gt; 1000 1010</li><li>-1 -&gt; 1000 0001</li><li>1 -&gt; 0000 0001</li></ul><p>问题：原码在做计算的时候会出现一些问题，比如正负数的加法运算，以及零的问题。</p><p>正负数加法</p><ul><li>-1 + 1 = 0</li></ul><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  1000 0001</span></span>
<span class="line"><span>+ 0000 0001</span></span>
<span class="line"><span>----------------</span></span>
<span class="line"><span>  1000 0010 -&gt; -2 ?</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>正负零</p><ul><li>+0 和 -0</li><li>十进制数字0，占了两个二进制；</li></ul><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0000 0000</span></span>
<span class="line"><span>1000 0000</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="反码" tabindex="-1">反码 <a class="header-anchor" href="#反码" aria-label="Permalink to &quot;反码&quot;">​</a></h3><div class="tip custom-block github-alert"><p class="custom-block-title">为了解决上面的问题，出现了反码，反码的计算规则如下：<br></p><p>正数的反码就是原码本身；<br> 负数的反码是按位取反（但符号位不变）；<br></p></div><p>示例</p><ul><li>1 -&gt; 0000 0001 -&gt; 0000 0001</li><li>-1 -&gt; 1000 0001 -&gt; 1111 1110</li></ul><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  0000 0001</span></span>
<span class="line"><span>+ 1111 1110</span></span>
<span class="line"><span>-----------------</span></span>
<span class="line"><span>  1111 1111</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>1111 1111 是运算完之后的结果，但要注意，这时还是反码，需要重新返回来：1000 0000 。 反码解决了正负数加法问题，但正负零的问题还是存在。</p><h3 id="补码" tabindex="-1">补码 <a class="header-anchor" href="#补码" aria-label="Permalink to &quot;补码&quot;">​</a></h3><div class="tip custom-block github-alert"><p class="custom-block-title">正数的补码就是原码本身；</p><p></p><p>负数的补码就是在反码的基础上+1</p></div><ul><li>1 -&gt; 0000 0001 -&gt; 0000 0001 -&gt; 0000 0001</li><li>-1 -&gt; 1000 0001 -&gt; 1111 1110 -&gt; 1111 1111</li></ul><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  0000 0001</span></span>
<span class="line"><span>+ 1111 1111</span></span>
<span class="line"><span>----------------</span></span>
<span class="line"><span>  0000 0000</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>补码在正负数加减法运算时没问题，也不会出现正负零占两个二进制。但 1000 0000 不表示为负零，用来表示什么呢？计算机其实默认把8位有符号二进制 1000 0000 表示为 -128 。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int8_t e = 0b10000000;</span></span>
<span class="line"><span>printf(&quot;%d\\n&quot;, e);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h3><p>正数的反码和补码都是自己本身！！！</p><p>负数用补码来表示！！！</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>在有符号数中，负数用补码表示：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>规则：负数的补码 = 其绝对值的二进制取反 + 1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>例子：-1 的计算过程</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1的二进制：0000 0001</span></span>
<span class="line"><span></span></span>
<span class="line"><span>取反：1111 1110</span></span>
<span class="line"><span></span></span>
<span class="line"><span>加1：1111 1111 ✓</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><h2 id="数值范围" tabindex="-1">数值范围 <a class="header-anchor" href="#数值范围" aria-label="Permalink to &quot;数值范围&quot;">​</a></h2><p>一个字节（8bit），能表示的数据范围（用原码表示）：</p><ol><li>uint8_t无符号数： (0 ~ 255) 0000 0000 ~ 1111 1111</li><li>int8_t有符号数： (-127 ~ 0 ~ 127) 1000 0001 ~ 0000 0000 ~ 0111 1111</li><li>int8_t有符号数：（-128 ） 1000 0000</li></ol><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;stdint.h&gt;  // 提供 int8_t, uint8_t</span></span>
<span class="line"><span></span></span>
<span class="line"><span>int main() {</span></span>
<span class="line"><span>    // 1. int - 原生类型，大小依赖平台</span></span>
<span class="line"><span>    int a = 1000;</span></span>
<span class="line"><span>    printf(&quot;int 大小: %zu 字节\\n&quot;, sizeof(int));     // 通常是 4</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    // 2. int8_t - 固定8位有符号</span></span>
<span class="line"><span>    int8_t b = 100;</span></span>
<span class="line"><span>    // int8_t b2 = 200;  // ❌ 警告：超出范围（最大127）</span></span>
<span class="line"><span>    printf(&quot;int8_t 大小: %zu 字节\\n&quot;, sizeof(int8_t));  // 固定 1</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    // 3. uint8_t - 固定8位无符号</span></span>
<span class="line"><span>    uint8_t c = 200;</span></span>
<span class="line"><span>    // uint8_t c2 = -10;  // ❌ 不能赋负数</span></span>
<span class="line"><span>    printf(&quot;uint8_t 大小: %zu 字节\\n&quot;, sizeof(uint8_t)); // 固定 1</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    // 4. 尝试 int8（不存在）</span></span>
<span class="line"><span>    // int8 d = 10;  // ❌ 编译错误</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br></div></div><p>结果</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int 大小: 4 字节</span></span>
<span class="line"><span>int8_t 大小: 1 字节</span></span>
<span class="line"><span>uint8_t 大小: 1 字节</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div>`,51)])])}const y=n(c,[["render",b]]);export{f as __pageData,y as default};
